// Code node: Valida | Exclusão Confirmada
// Mode: Run Once for All Items
//
// O DELETE pode terminar no WordPress mesmo quando a confirmação posterior
// recebe timeout ou rate limit. Respostas transitórias não encerram o fluxo:
// elas seguem para Wait e repetem somente o GET de confirmação.

const r = $json;
const ctx = $('Loop | Exclusões').item.json;

const migrationId = Number(ctx.migration_id);
const originalId = Number(ctx.wp_media_id_original);

if (
  !Number.isSafeInteger(migrationId) ||
  migrationId <= 0 ||
  !Number.isSafeInteger(originalId) ||
  originalId <= 0
) {
  throw new Error(
    `Contexto inválido na confirmação da exclusão | ` +
    `migration=${ctx.migration_id} | ` +
    `original=${ctx.wp_media_id_original}`
  );
}

const body =
  r.body && typeof r.body === 'object'
    ? r.body
    : r;

const httpStatus = Number(
  body.origin_status ??
  r.statusCode ??
  0
);

let originBody = {};

if (
  typeof body.origin_body === 'string' &&
  body.origin_body.trim()
) {
  try {
    originBody = JSON.parse(body.origin_body);
  } catch {
    originBody = {};
  }
} else if (
  body.origin_body &&
  typeof body.origin_body === 'object'
) {
  originBody = body.origin_body;
} else if (
  body &&
  typeof body === 'object'
) {
  originBody = body;
}

const originCode =
  originBody.code ??
  null;

const target =
  String(body.target ?? '');

if (target) {
  const match = target.match(
    /\/wp\/v2\/media\/(\d+)(?:[/?#]|$)/
  );

  if (
    !match ||
    Number(match[1]) !== originalId
  ) {
    throw new Error(
      `Resposta de outra mídia | ` +
      `migration=${migrationId} | ` +
      `media=${originalId} | ` +
      `target=${target}`
    );
  }
}

// Confirmação definitiva de que a mídia original não existe.
const exclusaoConfirmada =
  httpStatus === 404 &&
  originCode === 'rest_post_invalid_id';

if (exclusaoConfirmada) {
  return [{
    json: {
      ...ctx,

      migration_id: migrationId,
      wp_media_id_original: originalId,

      exclusao_confirmada: true,
      confirmacao_pendente: false,

      exclusao_http_status: httpStatus,
      exclusao_origin_code: originCode,

      confirmacao_retry_after: 0,
      confirmacao_status: 'EXCLUIDA'
    },

    pairedItem: {
      item: 0
    }
  }];
}

// Respostas transitórias: repetir somente o GET.
const statusTransitorios = new Set([
  408,
  425,
  429,
  500,
  502,
  503,
  504,
  520,
  521,
  522,
  523,
  524
]);

if (statusTransitorios.has(httpStatus)) {
  const retryAfterInformado = Number(
    originBody.retry_after ??
    body.retry_after ??
    r.headers?.['retry-after'] ??
    0
  );

  const retryAfter = Math.max(
    Number.isFinite(retryAfterInformado)
      ? retryAfterInformado
      : 0,
    httpStatus === 429 || httpStatus === 504
      ? 120
      : 60
  );

  return [{
    json: {
      ...ctx,

      migration_id: migrationId,
      wp_media_id_original: originalId,

      exclusao_confirmada: false,
      confirmacao_pendente: true,

      exclusao_http_status: httpStatus,
      exclusao_origin_code: originCode,

      confirmacao_retry_after: retryAfter,
      confirmacao_status: 'PENDENTE_RETRY_GET',
      confirmacao_motivo:
        originBody.error_name ??
        body.origin_status_text ??
        r.statusMessage ??
        `HTTP_${httpStatus}`
    },

    pairedItem: {
      item: 0
    }
  }];
}

// HTTP 200 significa que a mídia continua existindo.
// Não pode ser interpretado como exclusão concluída.
if (httpStatus === 200) {
  throw new Error(
    `Mídia original ainda existe após DELETE | ` +
    `migration=${migrationId} | ` +
    `media=${originalId} | HTTP=200`
  );
}

throw new Error(
  `Exclusão não confirmada | ` +
  `migration=${migrationId} | ` +
  `media=${originalId} | ` +
  `HTTP=${httpStatus || 'N/A'} | ` +
  `code=${originCode || 'N/A'}`
);

const respostas = $input.all();
const contextos = $('Valida | Contrato Exclusão').all();

// Indexa pelo ID da mídia original
const mapa = new Map(
  contextos.map(item => [
    Number(item.json.wp_media_id_original),
    item.json
  ])
);

function getOriginBody(r) {
  const raw = r.body?.origin_body;

  if (typeof raw !== 'string') {
    return {};
  }

  try {
    return JSON.parse(raw);
  } catch {
    return {};
  }
}

return respostas.map((item, index) => {

  const r = item.json;

  const body =
    r.body &&
    typeof r.body === 'object'
      ? r.body
      : r;

  const httpStatus = Number(
    body.origin_status ??
    r.statusCode ??
    0
  );

  const originBody = getOriginBody(r);

  // -------------------------------------------------------
  // Identifica qual wp_media_id_original esta resposta
  // pertence.
  //
  // 200 → WordPress retorna media.id
  // erro → proxy retorna target .../media/XXXX
  // fallback → mesma posição do contexto
  // -------------------------------------------------------

  let originalId =
    Number(body.id ?? 0);

  if (!originalId) {
    const target = String(
      body.target ??
      r.body?.target ??
      ''
    );

    const match =
      target.match(/\/media\/(\d+)/);

    if (match) {
      originalId = Number(match[1]);
    }
  }

  let ctx =
    mapa.get(originalId);

  // Fallback seguro para resposta HTTP que não carregue ID
  if (!ctx && contextos[index]) {
    ctx = contextos[index].json;
    originalId =
      Number(ctx.wp_media_id_original);
  }

  if (!ctx) {
    throw new Error(
      `Contexto não encontrado na classificação da mídia original`
    );
  }

  const migrationId =
    Number(ctx.migration_id);

  // -------------------------------------------------------
  // ORIGINAL EXISTE
  // -------------------------------------------------------

  if (httpStatus === 200) {

    if (
      Number(body.id) !==
      Number(ctx.wp_media_id_original)
    ) {
      throw new Error(
        `Migration ${migrationId}: ` +
        `ID da mídia original divergente`
      );
    }

    return {
      json: {
        ...ctx,

        original_http_status: 200,
        original_existe: true,
        original_ja_excluida: false,

        precisa_excluir_original: true
      }
    };
  }

  // -------------------------------------------------------
  // ORIGINAL JÁ FOI EXCLUÍDA
  // -------------------------------------------------------

  if (
    httpStatus === 404 &&
    originBody.code === 'rest_post_invalid_id'
  ) {

    return {
      json: {
        ...ctx,

        original_http_status: 404,
        original_existe: false,
        original_ja_excluida: true,

        precisa_excluir_original: false
      }
    };
  }

  // -------------------------------------------------------
  // ERRO TRANSITÓRIO
  //
  // Não pode cair no FALSE do IF, porque FALSE significa
  // "original já excluída".
  // -------------------------------------------------------

  if (
    [
      403,
      408,
      429,
      500,
      502,
      503,
      504,
      520,
      522,
      523,
      524
    ].includes(httpStatus)
  ) {

    throw new Error(
      `Falha transitória ao verificar mídia original | ` +
      `migration=${migrationId} | ` +
      `media=${originalId} | ` +
      `HTTP=${httpStatus}`
    );
  }

  // -------------------------------------------------------
  // QUALQUER OUTRA RESPOSTA
  // -------------------------------------------------------

  throw new Error(
    `Resposta inesperada ao verificar mídia original | ` +
    `migration=${migrationId} | ` +
    `media=${originalId} | ` +
    `HTTP=${httpStatus || 'N/A'}`
  );
});

const itens = $input.all();

return itens.map(item => {
  const ctx = item.json;

  if (
    ctx.precisa_excluir_original !== false ||
    ctx.original_ja_excluida !== true ||
    Number(ctx.original_http_status) !== 404
  ) {
    throw new Error(
      `Migration ${ctx.migration_id}: item não possui evidência válida ` +
      `de exclusão anterior da mídia ${ctx.wp_media_id_original}`
    );
  }

  return {
    json: {
      migration_id: Number(ctx.migration_id),
      post_id: Number(ctx.post_id),

      wp_media_id_original: Number(ctx.wp_media_id_original),
      wp_media_id_virtual: Number(ctx.wp_media_id_virtual),

      cloudinary_url: ctx.cloudinary_url,

      exclusao_original_confirmada: true,
      wp_original_http_status: 404,

      status_final: 'MIGRATED'
    }
  };
});

// Node: Monta | Lote Conclusão
// Mode: Run Once for All Items
// Somente auditorias 404/rest_post_invalid_id podem chegar à SP de conclusão.

const esperados = $('Recupera | Lote Auditoria Final').all();

if (esperados.length === 0) {
  throw new Error('Nenhum item esperado para conclusão do lote.');
}

const confirmados = [];
const nodesConfirmacao = [
  'Classifica | Auditoria Final',
  'Valida | Retry Auditoria Final',
];

// Os nodes de auditoria executam em runIndex diferentes dentro do loop.
for (const nodeName of nodesConfirmacao) {
  for (let runIndex = 0; runIndex < esperados.length; runIndex++) {
    try {
      const itensRun = $(nodeName).all(0, runIndex);

      if (Array.isArray(itensRun)) {
        confirmados.push(...itensRun);
      }
    } catch {
      // O node pode não ter executado nesta iteração.
    }
  }
}

const mapaEsperados = new Map();

for (const item of esperados) {
  const x = item.json;
  const migrationId = Number(x.migration_id);

  if (!Number.isSafeInteger(migrationId) || migrationId <= 0) {
    throw new Error('Lote de auditoria contém migration_id inválido.');
  }

  if (mapaEsperados.has(migrationId)) {
    throw new Error(
      `Migration ${migrationId}: duplicada no lote de auditoria.`
    );
  }

  mapaEsperados.set(migrationId, x);
}

const mapaConfirmados = new Map();

for (const item of confirmados) {
  const x = item.json;

  if (
    x.auditoria_confirmada !== true ||
    x.auditoria_status !== 'EXCLUIDA' ||
    Number(x.auditoria_http_status) !== 404 ||
    x.auditoria_origin_code !== 'rest_post_invalid_id'
  ) {
    continue;
  }

  const migrationId = Number(x.migration_id);
  const postId = Number(x.post_id);
  const originalId = Number(x.wp_media_id_original);
  const virtualId = Number(x.wp_media_id_virtual);
  const provider = String(x.storage_provider ?? '').trim();
  const storageUrl = String(x.storage_url ?? '').trim();
  const esperado = mapaEsperados.get(migrationId);

  if (!esperado) {
    throw new Error(
      `Migration ${migrationId}: auditoria não pertence ao lote atual.`
    );
  }

  if (
    !Number.isSafeInteger(migrationId) ||
    migrationId <= 0 ||
    !Number.isSafeInteger(postId) ||
    postId <= 0 ||
    !Number.isSafeInteger(originalId) ||
    originalId <= 0 ||
    !Number.isSafeInteger(virtualId) ||
    virtualId <= 0 ||
    !/^[a-z0-9_]{1,100}$/.test(provider) ||
    !/^https:\/\/[^/\s]+\/\S+$/.test(storageUrl)
  ) {
    throw new Error(
      `Migration ${migrationId}: confirmação de auditoria incompleta.`
    );
  }

  if (
    Number(esperado.post_id) !== postId ||
    Number(esperado.wp_media_id_original) !== originalId ||
    Number(esperado.wp_media_id_virtual) !== virtualId ||
    String(esperado.storage_provider ?? '').trim() !== provider ||
    String(esperado.storage_url ?? '').trim() !== storageUrl
  ) {
    throw new Error(
      `Migration ${migrationId}: auditoria diverge do lote esperado.`
    );
  }

  const anterior = mapaConfirmados.get(migrationId);

  if (
    anterior &&
    (
      anterior.post_id !== postId ||
      anterior.wp_media_id_original !== originalId ||
      anterior.wp_media_id_virtual !== virtualId
    )
  ) {
    throw new Error(
      `Migration ${migrationId}: confirmações de auditoria conflitantes.`
    );
  }

  mapaConfirmados.set(migrationId, {
    migration_id: migrationId,
    post_id: postId,
    wp_media_id_original: originalId,
    wp_media_id_virtual: virtualId,
    storage_provider: provider,
    storage_url: storageUrl,
  });
}

const pendentes = [...mapaEsperados.keys()]
  .filter(migrationId => !mapaConfirmados.has(migrationId))
  .sort((a, b) => a - b);

if (pendentes.length > 0) {
  throw new Error(
    `Conclusão bloqueada: auditoria final não confirmada para migrations ` +
    `${pendentes.join(', ')}.`
  );
}

const lote = [...mapaConfirmados.values()]
  .sort((a, b) => a.migration_id - b.migration_id);

if (lote.length !== esperados.length) {
  throw new Error(
    `Conclusão bloqueada: esperados=${esperados.length}, ` +
    `confirmados=${lote.length}.`
  );
}

return [{
  json: {
    total: lote.length,
    lote,
  },
}];

const itens = $('Valida | Contrato Exclusão').all();

if (itens.length === 0) {
  throw new Error('Nenhum item encontrado para auditoria final.');
}

return itens.map(item => {
  const x = item.json;

  const migrationId = Number(x.migration_id);
  const postId = Number(x.post_id);
  const originalId = Number(x.wp_media_id_original);
  const virtualId = Number(x.wp_media_id_virtual);
  const provider = String(x.storage_provider ?? '').trim();
  const storageUrl = String(x.storage_url ?? '').trim();

  if (
    !Number.isSafeInteger(migrationId) || migrationId <= 0 ||
    !Number.isSafeInteger(postId) || postId <= 0 ||
    !Number.isSafeInteger(originalId) || originalId <= 0 ||
    !Number.isSafeInteger(virtualId) || virtualId <= 0 ||
    !/^[a-z0-9_]{1,100}$/.test(provider) ||
    !/^https:\/\/[^/\s]+\/\S+$/.test(storageUrl) ||
    x.associacao_wp_confirmada !== true ||
    x.exclusao_liberada !== true
  ) {
    throw new Error(
      `Migration ${migrationId}: contexto incompleto para auditoria final.`
    );
  }

  return {
    json: {
      migration_id: migrationId,
      post_id: postId,
      wp_media_id_original: originalId,
      wp_media_id_virtual: virtualId,
      storage_provider: provider,
      storage_url: storageUrl,
      media_virtual_url: x.media_virtual_url ?? null,
      associacao_wp_confirmada: true,
      exclusao_liberada: true
    }
  };
});

const r = $json;

// Contexto original do item que está sendo auditado
const ctx = $('Loop | Auditoria Final').item.json;

// ---------------------------------------------------------
// STATUS HTTP
// Compatível com resposta direta e resposta do proxy
// ---------------------------------------------------------

const httpStatus = Number(
  r.body?.origin_status ??
  r.statusCode ??
  0
);

// ---------------------------------------------------------
// BODY ORIGINAL DO WORDPRESS
// ---------------------------------------------------------

let originBody = {};

// Quando o proxy encapsula o erro
if (typeof r.body?.origin_body === 'string') {
  try {
    originBody = JSON.parse(r.body.origin_body);
  } catch {
    originBody = {};
  }
}

// Caso eventualmente venha resposta direta
if (
  !Object.keys(originBody).length &&
  r.body &&
  typeof r.body === 'object'
) {
  originBody = r.body;
}

const originCode =
  originBody.code ?? null;

// ---------------------------------------------------------
// CLASSIFICAÇÃO
// ---------------------------------------------------------

let auditoriaStatus = 'ERRO_REAL';

// Mídia realmente não existe mais
if (
  httpStatus === 404 &&
  originCode === 'rest_post_invalid_id'
) {
  auditoriaStatus = 'EXCLUIDA';
}

// Original ainda existe
else if (httpStatus === 200) {
  auditoriaStatus = 'ORIGINAL_EXISTE';
}

// Falhas temporárias / infraestrutura / rate limit
else if (
  [
    403,
    408,
    429,
    500,
    502,
    503,
    504,
    520,
    522,
    523,
    524
  ].includes(httpStatus)
) {
  auditoriaStatus = 'TRANSITORIO';
}

// ---------------------------------------------------------
// RETORNO
// ---------------------------------------------------------

return [{
  json: {
    ...ctx,

    auditoria_status:
      auditoriaStatus,

    auditoria_http_status:
      httpStatus,

    auditoria_origin_code:
      originCode,

    auditoria_confirmada:
      auditoriaStatus === 'EXCLUIDA',

    auditoria_erro:
      auditoriaStatus === 'ERRO_REAL'
        ? (
            r.body?.origin_status_text ??
            r.statusMessage ??
            'Falha não classificada na auditoria final'
          )
        : null
  }
}];

const x = $json;

const migrationId =
  Number(x.migration_id ?? 0);

const mediaOriginal =
  Number(x.wp_media_id_original ?? 0);

const status =
  x.auditoria_status ?? 'DESCONHECIDO';

const http =
  Number(x.auditoria_http_status ?? 0);

throw new Error(
  `Auditoria final bloqueada | ` +
  `migration=${migrationId} | ` +
  `media_original=${mediaOriginal} | ` +
  `status=${status} | ` +
  `HTTP=${http || 'N/A'}`
);

const r = $json;
const ctx = $('Loop | Auditoria Final').item.json;

const httpStatus = Number(
  r.body?.origin_status ??
  r.statusCode ??
  0
);

let originBody = {};

if (typeof r.body?.origin_body === 'string') {
  try {
    originBody = JSON.parse(r.body.origin_body);
  } catch {}
}

const excluida =
  httpStatus === 404 &&
  originBody.code === 'rest_post_invalid_id';

if (!excluida) {
  throw new Error(
    `Auditoria final falhou após retry | ` +
    `migration=${ctx.migration_id} | ` +
    `media_original=${ctx.wp_media_id_original} | ` +
    `HTTP=${httpStatus || 'N/A'}`
  );
}

return [{
  json: {
    ...ctx,
    auditoria_status: 'EXCLUIDA',
    auditoria_http_status: httpStatus,
    auditoria_origin_code: originBody.code,
    auditoria_confirmada: true,
    auditoria_retry: true
  }
}];

const itens = $input.all();

return itens.map(item => {
  const x = item.json;

  const migrationId = Number(x.migration_id);
  const postId = Number(x.post_id);
  const originalId = Number(x.wp_media_id_original);
  const virtualId = Number(x.wp_media_id_virtual);
  const provider = String(x.storage_provider ?? '').trim();
  const storageUrl = String(x.storage_url ?? '').trim();

  if (
    !Number.isSafeInteger(migrationId) || migrationId <= 0 ||
    !Number.isSafeInteger(postId) || postId <= 0 ||
    !Number.isSafeInteger(originalId) || originalId <= 0 ||
    !Number.isSafeInteger(virtualId) || virtualId <= 0 ||
    originalId === virtualId
  ) {
    throw new Error(
      `Migration ${migrationId}: IDs inválidos para exclusão.`
    );
  }

  if (
    x.associacao_wp_confirmada !== true ||
    x.exclusao_liberada !== true
  ) {
    throw new Error(
      `Migration ${migrationId}: associação ou exclusão não confirmada.`
    );
  }

  if (
    !/^[a-z0-9_]{1,100}$/.test(provider) ||
    !/^https:\/\/[^/\s]+\/\S+$/.test(storageUrl)
  ) {
    throw new Error(
      `Migration ${migrationId}: storage canônico inválido.`
    );
  }

  return {
    json: {
      ...x,
      migration_id: migrationId,
      post_id: postId,
      wp_media_id_original: originalId,
      wp_media_id_virtual: virtualId,
      storage_provider: provider,
      storage_url: storageUrl
    },
    binary: item.binary
  };
});

// Node: Valida | Exclusão Confirmada Retry
// Mode: Run Once for All Items
// HTTP 200 exige novo DELETE; respostas transitórias repetem somente o GET.

const r = $json;
const ctx = $('Loop | Exclusões').item.json;

const migrationId = Number(ctx.migration_id);
const originalId = Number(ctx.wp_media_id_original);

if (
  !Number.isSafeInteger(migrationId) ||
  migrationId <= 0 ||
  !Number.isSafeInteger(originalId) ||
  originalId <= 0
) {
  throw new Error(
    `Contexto inválido na confirmação da exclusão | ` +
    `migration=${ctx.migration_id} | original=${ctx.wp_media_id_original}`
  );
}

const body = r.body && typeof r.body === 'object' ? r.body : r;
const httpStatus = Number(body.origin_status ?? r.statusCode ?? 0);

let originBody = {};

if (typeof body.origin_body === 'string' && body.origin_body.trim()) {
  try {
    originBody = JSON.parse(body.origin_body);
  } catch {
    originBody = {};
  }
} else if (body.origin_body && typeof body.origin_body === 'object') {
  originBody = body.origin_body;
} else if (body && typeof body === 'object') {
  originBody = body;
}

const originCode = originBody.code ?? null;
const target = String(body.target ?? '');

if (target) {
  const match = target.match(/\/wp\/v2\/media\/(\d+)(?:[/?#]|$)/);

  if (!match || Number(match[1]) !== originalId) {
    throw new Error(
      `Resposta de outra mídia | migration=${migrationId} | ` +
      `media=${originalId} | target=${target}`
    );
  }
}

const mediaRetornada = Number(body.id ?? 0);

if (
  httpStatus === 200 &&
  (!Number.isSafeInteger(mediaRetornada) || mediaRetornada !== originalId)
) {
  throw new Error(
    `GET retornou contexto divergente | migration=${migrationId} | ` +
    `media_esperada=${originalId} | media_retornada=${body.id ?? 'N/A'}`
  );
}

if (httpStatus === 404 && originCode === 'rest_post_invalid_id') {
  return [{
    json: {
      ...ctx,
      migration_id: migrationId,
      wp_media_id_original: originalId,
      exclusao_confirmada: true,
      confirmacao_pendente: false,
      repetir_exclusao: false,
      exclusao_acao: 'CONFIRMADA',
      exclusao_http_status: httpStatus,
      exclusao_origin_code: originCode,
      confirmacao_retry_after: 0,
    },
    pairedItem: { item: 0 },
  }];
}

if (httpStatus === 200) {
  return [{
    json: {
      ...ctx,
      migration_id: migrationId,
      wp_media_id_original: originalId,
      exclusao_confirmada: false,
      confirmacao_pendente: false,
      repetir_exclusao: true,
      exclusao_acao: 'REPETIR_DELETE',
      exclusao_http_status: httpStatus,
      exclusao_origin_code: null,
      confirmacao_retry_after: 120,
      confirmacao_motivo: 'MIDIA_ORIGINAL_AINDA_EXISTE',
    },
    pairedItem: { item: 0 },
  }];
}

const statusTransitorios = new Set([
  408,
  425,
  429,
  500,
  502,
  503,
  504,
  520,
  521,
  522,
  523,
  524,
]);

if (statusTransitorios.has(httpStatus)) {
  const retryAfterInformado = Number(
    originBody.retry_after ??
    body.retry_after ??
    r.headers?.['retry-after'] ??
    0
  );

  const retryAfter = Math.max(
    Number.isFinite(retryAfterInformado) ? retryAfterInformado : 0,
    httpStatus === 429 || httpStatus === 504 ? 120 : 60
  );

  return [{
    json: {
      ...ctx,
      migration_id: migrationId,
      wp_media_id_original: originalId,
      exclusao_confirmada: false,
      confirmacao_pendente: true,
      repetir_exclusao: false,
      exclusao_acao: 'REPETIR_GET',
      exclusao_http_status: httpStatus,
      exclusao_origin_code: originCode,
      confirmacao_retry_after: retryAfter,
      confirmacao_motivo:
        originBody.error_name ??
        body.origin_status_text ??
        r.statusMessage ??
        `HTTP_${httpStatus}`,
    },
    pairedItem: { item: 0 },
  }];
}

throw new Error(
  `Exclusão não confirmada | migration=${migrationId} | ` +
  `media=${originalId} | HTTP=${httpStatus || 'N/A'} | ` +
  `code=${originCode || 'N/A'}`
);

// =========================================================
// 1. RECUPERA MIGRATIONS CONCLUÍDAS PELO NOVO FILHO 2
// =========================================================

const retornoExclusao =
  $('Chamar | Exclusão e Auditoria').all();

const migrados = [];

// O subfluxo pode retornar:
// - um resultset como array
// - objetos individuais
// - metadata estrutural do MySQL
for (const item of retornoExclusao) {

  const value = item.json;

  // ResultSet MySQL
  if (Array.isArray(value)) {

    for (const registro of value) {

      if (
        registro?.migration_id &&
        registro?.status === 'MIGRATED'
      ) {
        migrados.push(registro);
      }

    }

    continue;
  }

  // Objeto funcional direto
  if (
    value?.migration_id &&
    value?.status === 'MIGRATED'
  ) {
    migrados.push(value);
  }
}


// =========================================================
// 2. REMOVE EVENTUAIS DUPLICIDADES
// =========================================================

const mapaMigrados = new Map();

for (const item of migrados) {
  mapaMigrados.set(
    Number(item.migration_id),
    item
  );
}

const loteConcluido =
  [...mapaMigrados.values()];


// =========================================================
// 3. VALIDA LOTE CONCLUÍDO
// =========================================================

if (loteConcluido.length === 0) {
  throw new Error(
    'Nenhuma migration MIGRATED retornada pelo subfluxo de Exclusão e Auditoria.'
  );
}


// =========================================================
// 4. RECUPERA RESULTADO DO CHECKPOINT
// =========================================================

const checkpointRaw = $input.all();

let checkpoint = null;

for (const item of checkpointRaw) {

  const value = item.json;

  // ResultSet retornado pela SP
  if (Array.isArray(value)) {

    const encontrado =
      value.find(x => x?.resultado);

    if (encontrado) {
      checkpoint = encontrado;
      break;
    }
  }

  // Compatibilidade com retorno direto
  if (value?.resultado) {
    checkpoint = value;
    break;
  }
}


// =========================================================
// 5. NORMALIZA POSTS MIGRADOS
// =========================================================

const posts = loteConcluido.map(item => {

  const postId =
    Number(item.post_id);

  return {

    migration_id:
      Number(item.migration_id),

    post_id:
      postId,

    url_publica:
      `https://energialimpa.live/?p=${postId}`,

    wp_media_id_original:
      Number(item.wp_media_id_original),

    wp_media_id_virtual:
      Number(item.wp_media_id_virtual),

    cloudinary_url:
      item.cloudinary_url
  };
});


// =========================================================
// 6. HTML DOS POSTS
// =========================================================

const listaHtml = posts
  .map(post => `
    <div style="margin-bottom:16px;padding-bottom:12px;border-bottom:1px solid #ddd;">
      <strong>Post ID:</strong> ${post.post_id}<br>

      <strong>Migration ID:</strong> ${post.migration_id}<br>

      <strong>URL:</strong>
      <a
        href="${post.url_publica}"
        target="_blank"
      >
        ${post.url_publica}
      </a>
    </div>
  `)
  .join('');


// =========================================================
// 7. CHECKPOINT
// =========================================================

const statusCheckpoint =
  checkpoint?.resultado ??
  'NÃO INFORMADO';

const totalResolvidos =
  checkpoint?.total_resolvidos ??
  '-';

const totalCandidatos =
  checkpoint?.total_candidatos ??
  '-';

const paginaAtual =
  checkpoint?.pagina_atual ??
  '-';


// =========================================================
// 8. SAÍDA PARA GMAIL
// =========================================================

return [
  {
    json: {

      assunto:
        `Migração Featured concluída | ${posts.length} posts`,

      total_migrados_lote:
        posts.length,

      checkpoint_status:
        statusCheckpoint,

      total_resolvidos:
        totalResolvidos,

      total_candidatos:
        totalCandidatos,

      pagina_atual:
        paginaAtual,

      posts,

      html: `
        <h2>Migração Featured concluída</h2>

        <p>
          <strong>Migrados nesta execução:</strong>
          ${posts.length}<br>

          <strong>Checkpoint:</strong>
          ${statusCheckpoint}<br>

          <strong>Resolvidos:</strong>
          ${totalResolvidos}/${totalCandidatos}<br>

          <strong>Página atual:</strong>
          ${paginaAtual}
        </p>

        <h3>Posts para conferência visual</h3>

        ${listaHtml}
      `
    }
  }
];
